function loadSavedData(){try{const current=JSON.parse(localStorage.getItem(KURRO_CACHE_KEY)||'null'),backup=JSON.parse(localStorage.getItem(KURRO_CACHE_BACKUP_KEY)||'null'),cached=current&&(current.center?.length||current.pending?.length)?current:backup;if(!cached)return false;centerRows.splice(0,centerRows.length,...(cached.center||[]));pendingRows.splice(0,pendingRows.length,...(cached.pending||[]));return centerRows.length>0||pendingRows.length>0}catch(e){return false}}
function saveData(){try{const snapshot={center:centerRows.map(r=>({...r})),pending:pendingRows.map(r=>({...r})),updated:new Date().toISOString()};const current=localStorage.getItem(KURRO_CACHE_KEY);if(current)try{const parsed=JSON.parse(current);if((parsed.center?.length||parsed.pending?.length)&&JSON.stringify(parsed)!==JSON.stringify(snapshot))localStorage.setItem(KURRO_CACHE_BACKUP_KEY,current)}catch(e){}localStorage.setItem(KURRO_CACHE_KEY,JSON.stringify(snapshot))}catch(e){}}
function metric(label,value,note,alert=false){return `<div class="metric ${alert?'alert':''}"><div class="metric-label">${label}</div><div class="metric-value">${value}</div><div class="metric-note">${note}</div></div>`}
function statusTag(s){const label=s==='done'?'REALIZADO':s==='process'?'EN PROCESO':'PENDIENTE';return `<span class="status ${s==='done'?'done':s==='process'?'process':'open'}"><span class="status-dot"></span>${label}</span>`}
function addMonths(date, months){const d=new Date(date+'T12:00:00');const day=d.getDate();d.setMonth(d.getMonth()+months);if(d.getDate()!==day)d.setDate(0);return d}
function nextDate(date,frequency){const d=new Date(date+'T12:00:00');const f=(frequency||'').toLowerCase();if(f.includes('seman'))d.setDate(d.getDate()+7);else if(f.includes('bimes'))return addMonths(date,2);else if(f.includes('trimes'))return addMonths(date,3);else if(f.includes('semes'))return addMonths(date,6);else if(f.includes('mens'))return addMonths(date,1);else if(f.includes('5 años'))return addMonths(date,60);else if(f.includes('3 años'))return addMonths(date,36);else if(f.includes('año')||f.includes('anual'))return addMonths(date,12);else return null;return d}
function formatDate(d){return d?`${String(d.getDate()).padStart(2,'0')}/${String(d.getMonth()+1).padStart(2,'0')}/${d.getFullYear()}`:''}
function normalizeSheetDate(value){const s=String(value||'').trim();let m=s.match(/^(\d{1,2})\/(\d{1,2})\/(\d{4})$/);if(m)return`${m[1].padStart(2,'0')}/${m[2].padStart(2,'0')}/${m[3]}`;m=s.match(/^(\d{4})-(\d{1,2})-(\d{1,2})$/);return m?`${m[3].padStart(2,'0')}/${m[2].padStart(2,'0')}/${m[1]}`:s}
function isOverdue(r){if(!r.next)return false;const p=r.next.split('/');const due=new Date(`${p[2]}-${p[1]}-${p[0]}T23:59:59`);return due<new Date()}
function dueTone(r){if(!r.next)return '';const p=r.next.split('/');const due=new Date(`${p[2]}-${p[1]}-${p[0]}T23:59:59`);const days=Math.ceil((due-new Date())/86400000);return days<0?'row-overdue':days<=30?'row-soon':'row-ok'}
function effectiveStatus(r){return isOverdue(r)&&r.status==='done'?'open':r.status}
function markCenterDone(index){const input=$(`done-date-${index}`);if(!input||!input.value){$('toast').textContent='Elige primero la fecha en la que se ha hecho';$('toast').classList.add('show');setTimeout(()=>$('toast').classList.remove('show'),2800);return}const r=centerRows[index];if(isOverdue(r)){r.status='process';$('toast').textContent='Esta actividad está vencida y no puede marcarse como realizada. Déjala pendiente o en proceso.';$('toast').classList.add('show');setTimeout(()=>$('toast').classList.remove('show'),3600);renderCenter();return}r.last=formatDate(new Date(input.value+'T12:00:00'));const next=nextDate(input.value,r.frequency);r.next=formatDate(next);r.status='done';r.action='REALIZADO';renderCenter();$('toast').textContent=next?`Marcado como hecho. Próxima revisión: ${r.next}`:'Marcado como hecho. Esta actividad no tiene periodicidad calculable.';$('toast').classList.add('show');setTimeout(()=>$('toast').classList.remove('show'),3200)}
function updateCenterField(index,field,value){const r=centerRows[index];if(field==='status'&&value==='done'&&isOverdue(r)){r.status='process';$('toast').textContent='Una actividad vencida solo puede estar pendiente o en proceso';$('toast').classList.add('show');setTimeout(()=>$('toast').classList.remove('show'),3000);renderCenter();return}r[field]=value;saveData();}
function sortValue(r,key){if(key==='category')return r.category;if(key==='last')return r.last?new Date(r.last.split('/').reverse().join('-')):new Date(0);if(key==='next')return r.next?new Date(r.next.split('/').reverse().join('-')):new Date(8640000000000000);if(key==='frequency')return r.frequency||'zzzz';if(key==='status')return r.status;return r.activity}
function renderCenter(){const q=($('center-search').value||'').toLowerCase(), cat=$('center-category').value, state=$('center-status').value, sort=$('center-sort').value;const rows=centerRows.filter(r=>(cat==='all'||r.category===cat)&&(state==='all'||(state==='done'?effectiveStatus(r)==='done':state==='process'?effectiveStatus(r)==='process':effectiveStatus(r)==='open'))&&[r.activity,r.category,r.frequency,r.last,r.next,r.owner,r.action].join(' ').toLowerCase().includes(q)).sort((a,b)=>{const av=sortValue(a,sort),bv=sortValue(b,sort);return av>bv?1:av<bv?-1:0});$('center-table').innerHTML=rows.length?rows.map(r=>{const i=centerRows.indexOf(r),st=effectiveStatus(r),overdue=isOverdue(r);return `<tr class="${dueTone(r)}"><td>${r.activity}</td><td>${r.category}</td><td>${r.frequency||'<span class="muted">Sin periodicidad</span>'}</td><td class="date">${normalizeSheetDate(r.last)||'<span class="muted">Sin fecha</span>'}</td><td class="date">${normalizeSheetDate(r.next)||'<span class="muted">Sin fecha</span>'}${overdue?' <span class="overdue-label">VENCIDA</span>':''}</td><td>${r.owner||'<span class="muted">Sin asignar</span>'}</td><td>${statusTag(st)}</td><td>${r.action||'<span class="muted">Sin comentarios</span>'}</td><td><div class="row-actions"><input id="done-date-${i}" type="date" aria-label="Fecha de la actuación para ${r.activity}" ${overdue?'disabled':''}/><button class="done-btn" onclick="${overdue?`openCenterEditor(${i})`:`markCenterDone(${i})`}">${overdue?'Registrar seguimiento':'Registrar revisión'}</button><button class="edit-btn" onclick="openCenterEditor(${i})">Editar</button></div></td></tr>`}).join(''):`<tr><td colspan="9" class="empty">No hay resultados con estos filtros.</td></tr>`;$('center-count').textContent=`${rows.length} registros`;}
function renderPending(){const q=($('pending-search').value||'').toLowerCase(), person=window.person||'all', priority=$('pending-priority').value,state=$('pending-status').value;const rows=pendingRows.filter(r=>(person==='all'||r.person===person)&&(priority==='all'||r.priority===priority)&&(state==='all'||r.status===state)&&[r.person,r.text,r.priority].join(' ').toLowerCase().includes(q));$('pending-table').innerHTML=rows.length?rows.map(r=>`<tr><td>${r.status==='PENDIENTE'?'<span class="status open"><span class="status-dot"></span>PENDIENTE</span>':'<span class="status done">REALIZADO</span>'}</td><td>${r.text}</td><td><strong>${r.person}</strong></td><td><span class="priority">${r.priority}</span></td><td class="date">${r.date||'<span class="muted">Sin fecha</span>'}</td><td class="date">${r.updated}</td></tr>`).join(''):`<tr><td colspan="6" class="empty">No hay resultados con estos filtros.</td></tr>`;$('pending-heading').textContent=person==='all'?'Todos mis pendientes':`Pendientes con ${person}`;$('pending-count').textContent=`${rows.length} registros`;}
function init(){const cats=[...new Set(centerRows.map(r=>r.category))].sort();$('center-category').innerHTML='<option value="all">Todas las categorías</option>'+cats.map(c=>`<option>${c}</option>`).join('');$('center-metrics').innerHTML=metric('Actividades registradas',centerRows.length,'Registro maestro')+metric('Pendientes de centro',centerRows.filter(r=>r.status==='open').length,'Requieren seguimiento',true)+metric('En proceso',centerRows.filter(r=>r.status==='process').length,'Acciones abiertas')+metric('Próximas revisiones',centerRows.filter(r=>r.next).length,'Con fecha definida');$('pending-metrics').innerHTML=metric('Pendientes totales',pendingRows.length,'Miguel + Properval')+metric('Con Miguel',pendingRows.filter(r=>r.person==='Miguel').length,'Seguimiento activo')+metric('Con Properval',pendingRows.filter(r=>r.person==='Properval').length,'Seguimiento activo')+metric('Con fecha objetivo',pendingRows.filter(r=>r.date).length,'Para priorizar');$('people-tabs').innerHTML=['all','Miguel','Properval'].map(p=>`<button class="person-tab ${p==='all'?'active':''}" data-person="${p}">${p==='all'?'Todos':p}</button>`).join('');document.querySelectorAll('.nav-item').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('.nav-item').forEach(x=>x.classList.remove('active'));b.classList.add('active');document.querySelectorAll('.view').forEach(v=>v.classList.remove('active-view'));$(`${b.dataset.view}-view`).classList.add('active-view');$('page-title').textContent=b.dataset.view==='center'?'Centro':'Mis pendientes'}));document.querySelectorAll('.person-tab').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('.person-tab').forEach(x=>x.classList.remove('active'));b.classList.add('active');window.person=b.dataset.person;renderPending()}));['center-search','center-category','center-status','center-sort'].forEach(id=>$(id).addEventListener('input',renderCenter));['pending-search','pending-priority','pending-status'].forEach(id=>$(id).addEventListener('input',renderPending));document.querySelectorAll('[data-toast]').forEach(b=>b.addEventListener('click',()=>{ $('toast').textContent=b.dataset.toast;$('toast').classList.add('show');setTimeout(()=>$('toast').classList.remove('show'),2800)}));renderCenter();renderPending();}loadSavedData();window.person='all';init();
