function clientDateForEditor(v){const p=String(v||'').split('/');return p.length===3?p[2]+'-'+p[1].padStart(2,'0')+'-'+p[0].padStart(2,'0'):''}
function clientDateFromEditor(v){const p=String(v||'').split('-');return p.length===3?p[2]+'/'+p[1]+'/'+p[0]:''}
function clientOptions(){const l=mergedKurroLists();return [...new Set([...(l.client||[]),...clientRows.map(r=>r.client)].map(v=>String(v||'').trim()).filter(Boolean))].sort((a,b)=>a.localeCompare(b,'es'))}
function refreshClientOptions(){const s=$('client-edit-client');if(!s)return;const v=s.value;s.innerHTML='<option value="">Sin asignar</option>'+clientOptions().map(x=>'<option>'+x+'</option>').join('');if(v)s.value=v}
function saveClientData(){try{localStorage.setItem('kurro-clients-v1',JSON.stringify(clientRows))}catch(e){}}
function loadClientData(){try{const cached=JSON.parse(localStorage.getItem('kurro-clients-v1')||'null');if(!Array.isArray(cached))return false;clientRows.splice(0,clientRows.length,...cached.filter(r=>r&&typeof r==='object'));clientsLoading=clientRows.length===0;return clientRows.length>0}catch(e){return false}}
function renderClientMetrics(){const open=clientRows.filter(r=>r.status!=='REALIZADO');$('client-metrics').innerHTML=metric('Pendientes activos',open.length,'Seguimiento con clientes',true)+metric('En proceso',open.filter(r=>r.status==='EN PROCESO').length,'Gestiones abiertas')+metric('Alta prioridad',open.filter(r=>r.priority==='ALTA').length,'Para atender')+metric('Con fecha objetivo',open.filter(r=>r.date).length,'Para organizar')}
function updateClientField(i,f,v){const r=clientRows[i];if(!r)return;r[f]=v;r.updated=formatDate(new Date());saveClientData();renderClients();if(r.serverRow)remoteWrite(kurroRequest({api:'updateClient',fileId:CLIENTS_FILE_ID,row:r.serverRow,field:f==='date'?'target':f,value:v}).catch(reportRemoteWriteFailure))}
function renderClients(){const q=($('client-search')?.value||'').toLowerCase(),pr=$('client-priority')?.value||'all',st=$('client-status')?.value||'PENDIENTE',rows=clientRows.filter(r=>(pr==='all'||r.priority===pr)&&(st==='all'||r.status===st)&&[r.client,r.contact,r.text,r.comments].join(' ').toLowerCase().includes(q));if(clientsLoading&&!clientRows.length){$('client-table').innerHTML='<tr><td colspan="9" class="empty">Cargando clientes desde Google Sheets…</td></tr>';$('client-count').textContent='Cargando…';return}$('client-table').innerHTML=rows.length?rows.map(r=>{const i=clientRows.indexOf(r);return '<tr><td><select class="status-select" onchange="updateClientField('+i+',\'status\',this.value)"><option '+(r.status==='PENDIENTE'?'selected':'')+'>PENDIENTE</option><option '+(r.status==='EN PROCESO'?'selected':'')+'>EN PROCESO</option><option '+(r.status==='REALIZADO'?'selected':'')+'>REALIZADO</option></select></td><td><strong>'+(r.client||'<span class=muted>Sin asignar</span>')+'</strong></td><td>'+(r.contact||'<span class=muted>Sin contacto</span>')+'</td><td>'+(r.text||'')+'</td><td><select class="status-select" onchange="updateClientField('+i+',\'priority\',this.value)"><option '+(r.priority==='NORMAL'?'selected':'')+'>NORMAL</option><option '+(r.priority==='ALTA'?'selected':'')+'>ALTA</option></select></td><td class="date"><input class="pending-date" type="date" value="'+clientDateForEditor(r.date)+'" onchange="updateClientField('+i+',\'date\',clientDateFromEditor(this.value))"></td><td class="date">'+(r.updated||'<span class=muted>Sin fecha</span>')+'</td><td><textarea class="comment-input" rows="2" placeholder="Añadir comentario" onchange="updateClientField('+i+',\'comments\',this.value)">'+(r.comments||'')+'</textarea></td><td><button class="done-btn" onclick="updateClientField('+i+',\'status\',\'REALIZADO\')" '+(r.status==='REALIZADO'?'disabled':'')+'>Hecho</button> <button class="edit-btn" onclick="openClientEditor('+i+')">Editar</button></td></tr>'}).join(''):'<tr><td colspan="9" class="empty">No hay pendientes con estos filtros. Pulsa «Nuevo pendiente» para añadir el primero.</td></tr>';$('client-count').textContent=rows.length+' registros';renderClientMetrics()}
function openClientEditor(i=-1){clientEditorIndex=i;const r=i<0?{}:clientRows[i];refreshClientOptions();$('client-edit-client').value=r.client||'';$('client-edit-contact').value=r.contact||'';$('client-edit-text').value=r.text||'';$('client-edit-priority').value=r.priority||'NORMAL';$('client-edit-status').value=r.status||'PENDIENTE';$('client-edit-date').value=clientDateForEditor(r.date);$('client-edit-comments').value=r.comments||'';$('client-editor-title').textContent=i<0?'Nuevo pendiente':'Editar pendiente';$('client-editor').classList.add('open');$('client-editor').setAttribute('aria-hidden','false')}
function closeClientEditor(){$('client-editor').classList.remove('open');$('client-editor').setAttribute('aria-hidden','true');clientEditorIndex=-1}
async function saveClientEditor(){const text=$('client-edit-text').value.trim();if(!text){showSyncToast('Escribe el pendiente');return}const n=clientEditorIndex<0,r=n?{}:clientRows[clientEditorIndex];Object.assign(r,{client:$('client-edit-client').value.trim(),contact:$('client-edit-contact').value.trim(),text,priority:$('client-edit-priority').value,status:$('client-edit-status').value,date:$('client-edit-date').value?clientDateFromEditor($('client-edit-date').value):'',updated:formatDate(new Date()),comments:$('client-edit-comments').value});if(n){r.serverRow=Math.max(1,...clientRows.map(x=>x.serverRow||1))+1;r.fileId=CLIENTS_FILE_ID;clientRows.push(r)}saveClientData();renderClients();closeClientEditor();showSyncToast(n?'Añadiendo pendiente…':'Guardando pendiente…');try{await remoteWrite(Promise.all(Object.entries({status:r.status,client:r.client,contact:r.contact,task:r.text,priority:r.priority,target:r.date,updated:r.updated,comments:r.comments}).map(([field,value])=>kurroRequest({api:'updateClient',fileId:CLIENTS_FILE_ID,row:r.serverRow,field,value}))));showSyncToast(n?'Pendiente añadido':'Pendiente guardado')}catch(e){showSyncToast('Guardado local; falta publicar la conexión de clientes')}}
function remoteClientRow(row,i){return{status:String(row[0]||'PENDIENTE').toUpperCase(),client:row[1]||'',contact:row[2]||'',text:row[3]||'',priority:String(row[4]||'NORMAL').toUpperCase(),date:row[5]||'',updated:row[6]||'',comments:row[7]||'',closed:row[8]||'',serverRow:i+2,fileId:CLIENTS_FILE_ID}}
function loadRemoteClients(d){if(!d?.values?.length)return;clientRows=d.values.slice(1).filter(r=>r.some(Boolean)).map((r,i)=>remoteClientRow(r,i));clientsLoading=false;saveClientData();renderClients()}
document.querySelector('[data-new-client]')?.addEventListener('click',()=>openClientEditor());document.querySelectorAll('[data-close-client]').forEach(b=>b.addEventListener('click',closeClientEditor));$('save-client-editor')?.addEventListener('click',saveClientEditor);$('add-client-option')?.addEventListener('click',()=>{const v=prompt('Nombre del nuevo cliente');if(!v?.trim())return;const l=savedKurroLists();l.client=[...(l.client||[]),v.trim()];saveKurroLists(l);refreshClientOptions();$('client-edit-client').value=v.trim()});['client-search','client-priority','client-status'].forEach(id=>$(id)?.addEventListener('input',renderClients));loadClientData();refreshClientOptions();renderClients();
const previousClientAwareLoad=loadRemoteData;loadRemoteData=async function(){const directClients=gvizRequest('Clientes').catch(()=>null);await previousClientAwareLoad();try{const d=window.kurroLastData||await kurroRequest({api:'data'});const clientValues=d?.clients?.values||[];const hasClientRows=clientValues.slice(1).some(row=>row.some(Boolean));const clients=hasClientRows?d.clients:(await directClients)||{id:KURRO_SOURCE_ID,name:'Clientes',values:[]};loadRemoteClients(clients);const c=await kurroRequest({api:'config'});saveRemoteKurroLists(c.values);refreshKurroPeopleOptions();refreshClientOptions()}catch(e){}};
document.querySelectorAll('.nav-item').forEach(b=>b.addEventListener('click',()=>{if(b.dataset.view==='clients')$('page-title').textContent='Pendientes con clientes'}));
loadRemoteData();
async function deleteClientEditor(){const i=clientEditorIndex,r=clientRows[i];if(!r||!confirm('¿Quieres eliminar este pendiente?'))return;clientRows.splice(i,1);saveClientData();closeClientEditor();renderClients();if(r.serverRow){try{await remoteWrite(Promise.all(['status','client','contact','task','priority','target','updated','comments','closed'].map(field=>kurroRequest({api:'updateClient',fileId:CLIENTS_FILE_ID,row:r.serverRow,field,value:''}))))}catch(e){showSyncToast('Eliminado en esta vista; falta publicar la conexión')}}showSyncToast('Pendiente eliminado')}
$('delete-client-editor')?.addEventListener('click',deleteClientEditor);

// Todas las tablas usan una única acción de fila: Editar.
function removeExtraRowActions(){
  document.querySelectorAll('#center-table .done-btn,#pending-table .done-btn,#client-table .done-btn').forEach(button=>button.remove());
  document.querySelectorAll('table .row-actions input[type="date"]').forEach(input=>input.remove());
}
const renderCenterWithSingleAction=renderCenter;
renderCenter=()=>{renderCenterWithSingleAction();removeExtraRowActions()};
const renderPendingWithSingleAction=renderPending;
renderPending=()=>{renderPendingWithSingleAction();removeExtraRowActions()};
const renderClientsWithSingleAction=renderClients;
renderClients=()=>{renderClientsWithSingleAction();removeExtraRowActions()};
removeExtraRowActions();

// Cada entrada en Centro parte de su configuración operativa habitual.
// El estado elegido filtra la tabla, pero no debe quedarse pegado al cambiar de vista.
document.querySelectorAll('.nav-item').forEach(button=>button.addEventListener('click',()=>{
  if(button.dataset.view!=='center')return;
  $('center-search').value='';
  $('center-category').value='all';
  $('center-status').value='open';
  $('center-sort').value='next';
  window.centerQuickFilter=null;
  renderCenter();
}));

// Las tablas se consultan en modo lectura; los cambios se hacen desde Editar.
function harmonizeTableRows(tableId){
  const table=$(tableId); if(!table)return;
  table.querySelectorAll('tr').forEach(row=>{
    row.querySelectorAll('select,input[type="date"],textarea').forEach(control=>{
      const cell=control.closest('td'); if(!cell)return;
      const value=control.tagName==='SELECT'?control.options[control.selectedIndex]?.text:(control.value||'');
      const text=document.createElement('span');
      text.className='table-value';
      text.textContent=value||'Sin fecha';
      control.replaceWith(text);
    });
    row.querySelectorAll('.done-btn').forEach(button=>button.remove());
  });
}
const renderPendingHomogeneous=renderPending;
renderPending=function(){renderPendingHomogeneous();harmonizeTableRows('pending-table')};
const renderClientsHomogeneous=renderClients;
renderClients=function(){renderClientsHomogeneous();harmonizeTableRows('client-table')};
renderPending();
renderClients();

// Conserva la configuración de cada vista al navegar por la aplicación.
const VIEW_FILTERS_KEY='kurro-view-filters-v1';
const VIEW_FILTER_FIELDS={
  center:['center-search','center-category','center-status','center-sort'],
  pending:['pending-search','pending-priority','pending-status'],
  clients:['client-search','client-priority','client-status']
};
function readViewFilters(){try{return JSON.parse(localStorage.getItem(VIEW_FILTERS_KEY)||'{}')}catch(e){return {}}}
function saveViewFilters(view){
  const fields=VIEW_FILTER_FIELDS[view]; if(!fields)return;
  const all=readViewFilters(); all[view]=Object.fromEntries(fields.map(id=>[id,$(id)?.value||'']));
  try{localStorage.setItem(VIEW_FILTERS_KEY,JSON.stringify(all))}catch(e){}
}
function restoreViewFilters(view){
  const fields=VIEW_FILTER_FIELDS[view],saved=readViewFilters()[view]; if(!fields||!saved)return;
  fields.forEach(id=>{if($(id)&&saved[id]!==undefined)$(id).value=saved[id]});
  if(view==='pending')renderPending();
  if(view==='clients')renderClients();
  if(view==='center')renderCenter();
}
Object.keys(VIEW_FILTER_FIELDS).forEach(view=>VIEW_FILTER_FIELDS[view].forEach(id=>{
  $(id)?.addEventListener('input',()=>saveViewFilters(view));
  $(id)?.addEventListener('change',()=>saveViewFilters(view));
}));
document.querySelectorAll('.nav-item').forEach(button=>button.addEventListener('click',()=>setTimeout(()=>restoreViewFilters(button.dataset.view),0)));
Object.keys(VIEW_FILTER_FIELDS).forEach(restoreViewFilters);

// Firebase es el almacenamiento principal cuando la usuaria ha iniciado sesión.
// Google Sheets se conserva como respaldo y como fuente de migración inicial.
const legacyKurroRequest=kurroRequest, legacyLoadGvizData=loadGvizData, legacyLoadRemoteData=loadRemoteData;
let firebaseBootstrapping=false;
function firebaseDataFromRows(){
  const planning=[['Actividad','Categoría','Periodicidad','Última revisión','Próxima revisión','','Responsable','', '', 'Siguiente acción / comentarios','', 'Estado'],...centerRows.map(r=>[r.activity||'',r.category||'',r.frequency||'',r.last||'',r.next||'','',r.owner||'','','',r.action||'', '',r.status==='done'?'REALIZADO':r.status==='process'?'EN PROCESO':'PENDIENTE'])];
  const pendingFor=person=>[['Estado','Comentarios','Pendiente / decisión','Prioridad','Fecha objetivo','Actualización','Cerrado','Fila'],...pendingRows.filter(r=>r.person===person).map((r,i)=>[r.status||'PENDIENTE',r.comments||'',r.text||'',r.priority||'NORMAL',r.date||'',r.updated||'',r.closed||'',r.serverRow||i+2])];
  const clients=[['Estado','Cliente','Contacto','Pendiente / decisión','Prioridad','Fecha objetivo','Actualización','Comentarios','Cerrado'],...clientRows.map(r=>[r.status||'PENDIENTE',r.client||'',r.contact||'',r.text||'',r.priority||'NORMAL',r.date||'',r.updated||'',r.comments||'',r.closed||''])];
  return {planning:{id:'firebase',name:'Registro Maestro',values:planning},miguel:{id:'firebase',name:'Seguimientos',values:pendingFor('Miguel')},properval:{id:'firebase',name:'Seguimientos',values:pendingFor('Properval')},clients:{id:'firebase',name:'Clientes',values:clients}};
}
function firebaseSnapshot(){return{center:centerRows.map(r=>({...r})),pending:pendingRows.map(r=>({...r})),clients:clientRows.map(r=>({...r})),lists:mergedKurroLists(),updated:new Date().toISOString()}}
async function firebaseData(){const snap=await firebaseDb.collection('appState').doc('main').get();if(!snap.exists)throw new Error('Firebase aún no tiene datos');const value=snap.data()||{};centerRows.splice(0,centerRows.length,...(value.center||[]));pendingRows.splice(0,pendingRows.length,...(value.pending||[]));clientRows.splice(0,clientRows.length,...(value.clients||[]));clientsLoading=false;if(value.lists)remoteKurroLists=value.lists;saveData();saveClientData();return firebaseDataFromRows()}
function firebasePersistSnapshot(){if(!firebaseDb||!firebaseUser)return Promise.reject(new Error('No hay sesión Firebase'));const payload=firebaseSnapshot();firebaseWriteQueue=firebaseWriteQueue.then(()=>firebaseDb.collection('appState').doc('main').set(payload,{merge:false}));return firebaseWriteQueue}
loadGvizData=async function(){if(firebaseUser&&!firebaseBootstrapping)return firebaseData();return legacyLoadGvizData()};
kurroRequest=async function(params){if(firebaseUser&&params.api!=='config'){if(params.api==='data')return firebaseData();await firebasePersistSnapshot();return{ok:true,result:{firebase:true}}}return legacyKurroRequest(params)};
function firebaseAuthMessage(text){const node=$('firebase-auth-message');if(node)node.textContent=text||''}
function openFirebaseAuth(){const modal=$('firebase-auth');if(modal){modal.classList.add('open');$('firebase-password')?.focus()}}
function closeFirebaseAuth(){$('firebase-auth')?.classList.remove('open');firebaseAuthMessage('')}
async function submitFirebaseAuth(mode){const password=$('firebase-password')?.value||'';if(password.length<6){firebaseAuthMessage('La contraseña debe tener al menos 6 caracteres.');return}try{firebaseAuthMessage(mode==='create'?'Creando tu acceso…':'Entrando…');if(mode==='create')await firebaseAuth.createUserWithEmailAndPassword(FIREBASE_ALLOWED_EMAIL,password);else await firebaseAuth.signInWithEmailAndPassword(FIREBASE_ALLOWED_EMAIL,password);closeFirebaseAuth()}catch(error){firebaseAuthMessage(error.code==='auth/email-already-in-use'?'Ese acceso ya existe. Pulsa Entrar.':error.code==='auth/wrong-password'?'La contraseña no es correcta.':'No se ha podido completar el acceso. Comprueba los datos.')}}
function addFirebaseAuthUI(){if($('firebase-auth'))return;document.body.insertAdjacentHTML('beforeend',`<div id="firebase-auth" class="modal" aria-hidden="true"><div class="modal-card pending-editor-card" role="dialog" aria-modal="true"><div class="modal-heading"><div><p class="eyebrow">ACCESO PRIVADO</p><h2>Entrar en Aroa Gestión</h2></div><button class="modal-close" type="button" aria-label="Cerrar" id="firebase-auth-close">×</button></div><p class="pending-editor-note">Usa el acceso de Optimizia para abrir y guardar tus datos en Firebase.</p><label class="editor-grid" style="display:grid;gap:6px;color:#557078;font-size:13px;font-weight:700">Correo electrónico<input value="${FIREBASE_ALLOWED_EMAIL}" disabled></label><label style="display:grid;gap:6px;margin-top:14px;color:#557078;font-size:13px;font-weight:700">Contraseña<input id="firebase-password" type="password" autocomplete="current-password" placeholder="Mínimo 6 caracteres"></label><p id="firebase-auth-message" class="pending-editor-note" aria-live="polite"></p><div class="modal-actions"><button class="secondary" type="button" id="firebase-auth-cancel">Cancelar</button><button class="secondary" type="button" id="firebase-auth-create">Crear mi acceso</button><button class="primary" type="button" id="firebase-auth-login">Entrar</button></div></div></div>`);$('firebase-auth-close').addEventListener('click',closeFirebaseAuth);$('firebase-auth-cancel').addEventListener('click',closeFirebaseAuth);$('firebase-auth-login').addEventListener('click',()=>submitFirebaseAuth('login'));$('firebase-auth-create').addEventListener('click',()=>submitFirebaseAuth('create'));const top=$('.top-actions');if(top&&!$('firebase-auth-open')){const button=document.createElement('button');button.id='firebase-auth-open';button.className='refresh-button';button.textContent='Acceso privado';button.addEventListener('click',openFirebaseAuth);top.insertBefore(button,top.firstChild)}}
async function startFirebase(){if(!window.firebase)return;try{firebase.initializeApp(FIREBASE_CONFIG);firebaseAuth=firebase.auth();firebaseDb=firebase.firestore();addFirebaseAuthUI();firebaseAuth.onAuthStateChanged(async user=>{if(user&&user.email!==FIREBASE_ALLOWED_EMAIL){await firebaseAuth.signOut();return}firebaseUser=user||null;if(!firebaseUser){if($('sync-label'))$('sync-label').textContent='Google Sheets · respaldo';return}try{firebaseBootstrapping=true;const existing=await firebaseDb.collection('appState').doc('main').get();if(existing.exists){await firebaseData()}else{await legacyLoadRemoteData();await firebasePersistSnapshot()}firebaseBootstrapping=false;refreshKURROMetrics();renderCenter();renderPending();renderClients();if($('sync-label'))$('sync-label').textContent='Firebase · sincronizado';setDataAlert('')}catch(error){firebaseBootstrapping=false;if($('sync-label'))$('sync-label').textContent='Firebase · pendiente de configurar';setDataAlert('Firebase está conectado, pero todavía no se ha podido cargar la copia principal. Google Sheets sigue disponible como respaldo.')}})}catch(error){console.warn('Firebase no disponible',error)}}
// Firebase REST fallback: algunos navegadores bloquean las librerías CDN de Firebase.
// La aplicación puede autenticarse y leer/escribir Firestore sin depender de ellas.
let restIdToken=localStorage.getItem('aroa_firebase_id_token')||'',restRefreshToken=localStorage.getItem('aroa_firebase_refresh_token')||'';
function fsEncode(value){if(value===null)return{nullValue:null};if(typeof value==='boolean')return{booleanValue:value};if(typeof value==='number')return{doubleValue:value};if(typeof value==='string')return{stringValue:value};if(Array.isArray(value))return{arrayValue:{values:value.map(fsEncode)}};if(typeof value==='object')return{mapValue:{fields:Object.fromEntries(Object.entries(value).map(([k,v])=>[k,fsEncode(v)]))}};return{nullValue:null}}
function fsDecode(value){if(!value)return null;if('nullValue'in value)return null;if('booleanValue'in value)return value.booleanValue;if('integerValue'in value)return Number(value.integerValue);if('doubleValue'in value)return value.doubleValue;if('stringValue'in value)return value.stringValue;if('timestampValue'in value)return value.timestampValue;if('arrayValue'in value)return(value.arrayValue.values||[]).map(fsDecode);if('mapValue'in value)return Object.fromEntries(Object.entries(value.mapValue.fields||{}).map(([k,v])=>[k,fsDecode(v)]));return null}
async function restAuth(mode,password){const endpoint=mode==='create'?'accounts:signUp':'accounts:signInWithPassword';const response=await fetch('https://identitytoolkit.googleapis.com/v1/'+endpoint+'?key='+FIREBASE_CONFIG.apiKey,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({email:FIREBASE_ALLOWED_EMAIL,password,returnSecureToken:true})});const data=await response.json();if(!response.ok)throw Object.assign(new Error(data.error?.message||'AUTH_ERROR'),{code:data.error?.message});restIdToken=data.idToken;restRefreshToken=data.refreshToken;localStorage.setItem('aroa_firebase_id_token',restIdToken);localStorage.setItem('aroa_firebase_refresh_token',restRefreshToken);return data}
async function restDocGet(){const r=await fetch('https://firestore.googleapis.com/v1/projects/'+FIREBASE_CONFIG.projectId+'/databases/(default)/documents/appState/main',{headers:{Authorization:'Bearer '+restIdToken}});if(r.status===404)return null;if(!r.ok)throw new Error('FIRESTORE_GET_'+r.status);return fsDecode({mapValue:{fields:r.json?{}:{}}})}
async function restRead(){const r=await fetch('https://firestore.googleapis.com/v1/projects/'+FIREBASE_CONFIG.projectId+'/databases/(default)/documents/appState/main',{headers:{Authorization:'Bearer '+restIdToken}});if(r.status===404)return null;if(!r.ok)throw new Error('FIRESTORE_GET_'+r.status);const doc=await r.json();return fsDecode({mapValue:{fields:doc.fields||{}}})}
async function restWrite(value){const r=await fetch('https://firestore.googleapis.com/v1/projects/'+FIREBASE_CONFIG.projectId+'/databases/(default)/documents/appState/main',{method:'PATCH',headers:{Authorization:'Bearer '+restIdToken,'Content-Type':'application/json'},body:JSON.stringify({fields:Object.fromEntries(Object.entries(value).map(([k,v])=>[k,fsEncode(v)]))})});if(!r.ok)throw new Error('FIRESTORE_WRITE_'+r.status)}
async function submitFirebaseRest(mode){const password=$('firebase-password')?.value||'';if(password.length<6){firebaseAuthMessage('La contraseña debe tener al menos 6 caracteres.');return}try{firebaseAuthMessage(mode==='create'?'Creando tu acceso…':'Entrando…');await restAuth(mode,password);closeFirebaseAuth();await finishFirebaseRest()}catch(error){const code=String(error.code||'');firebaseAuthMessage(code.includes('EMAIL_EXISTS')?'Ese acceso ya existe. Pulsa Entrar.':code.includes('INVALID_PASSWORD')?'La contraseña no es correcta.':'No se ha podido completar el acceso. Comprueba los datos.')}}
function addFirebaseRestUI(){if($('firebase-auth'))return;document.body.insertAdjacentHTML('beforeend',`<div id="firebase-auth" class="modal" aria-hidden="true"><div class="modal-card pending-editor-card" role="dialog" aria-modal="true"><div class="modal-heading"><div><p class="eyebrow">ACCESO PRIVADO</p><h2>Entrar en Aroa Gestión</h2></div><button class="modal-close" type="button" aria-label="Cerrar" id="firebase-auth-close">×</button></div><p class="pending-editor-note">Usa el acceso de Optimizia para abrir y guardar tus datos en Firebase.</p><label class="editor-grid" style="display:grid;gap:6px;color:#557078;font-size:13px;font-weight:700">Correo electrónico<input value="${FIREBASE_ALLOWED_EMAIL}" disabled></label><label style="display:grid;gap:6px;margin-top:14px;color:#557078;font-size:13px;font-weight:700">Contraseña<input id="firebase-password" type="password" autocomplete="current-password" placeholder="Mínimo 6 caracteres"></label><p id="firebase-auth-message" class="pending-editor-note" aria-live="polite"></p><div class="modal-actions"><button class="secondary" type="button" id="firebase-auth-cancel">Cancelar</button><button class="secondary" type="button" id="firebase-auth-create">Crear mi acceso</button><button class="primary" type="button" id="firebase-auth-login">Entrar</button></div></div></div>`);$('firebase-auth-close').addEventListener('click',closeFirebaseAuth);$('firebase-auth-cancel').addEventListener('click',closeFirebaseAuth);$('firebase-auth-login').addEventListener('click',()=>submitFirebaseRest('login'));$('firebase-auth-create').addEventListener('click',()=>submitFirebaseRest('create'));const top=$('.top-actions');if(top&&!$('firebase-auth-open')){const button=document.createElement('button');button.id='firebase-auth-open';button.className='refresh-button';button.textContent='Acceso privado';button.addEventListener('click',openFirebaseAuth);top.insertBefore(button,top.firstChild)}}
async function finishFirebaseRest(){firebaseUser={email:FIREBASE_ALLOWED_EMAIL};try{const existing=await restRead();if(existing){centerRows.splice(0,centerRows.length,...(existing.center||[]));pendingRows.splice(0,pendingRows.length,...(existing.pending||[]));clientRows.splice(0,clientRows.length,...(existing.clients||[]));if(existing.lists)remoteKurroLists=existing.lists;saveData();saveClientData()}else{await legacyLoadRemoteData();await restWrite(firebaseSnapshot())}firebaseSnapshot;refreshKURROMetrics();renderCenter();renderPending();renderClients();if($('sync-label'))$('sync-label').textContent='Firebase · sincronizado';setDataAlert('')}catch(error){firebaseUser=null;if($('sync-label'))$('sync-label').textContent='Google Sheets · respaldo';setDataAlert('Firebase no ha podido sincronizarse. Se mantienen los datos guardados y Google Sheets como respaldo.')}}
firebasePersistSnapshot=()=>restWrite(firebaseSnapshot());
loadGvizData=async function(){if(firebaseUser)return firebaseDataFromRows();return legacyLoadGvizData()};
kurroRequest=async function(params){if(firebaseUser){if(params.api==='data')return firebaseDataFromRows();await firebasePersistSnapshot();return{ok:true,result:{firebase:true}}}return legacyKurroRequest(params)};
async function startFirebaseRest(){addFirebaseRestUI();if(restIdToken)await finishFirebaseRest()}
startFirebaseRest();
